package cconv

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
	"testing"
)

// corpusCase is one string of testdata/corpus.txt together with the
// results the platform C library produced for it (testdata/expected.txt,
// generated by reference/harness/cconv).
type corpusCase struct {
	line  string // case line as written in the corpus (with '>')
	input string // decoded test string
	// strtol results per base (0, 10, 16, 8, 2, 36)
	long map[int]longResult
	// (int)strtol(s, &e, 0)
	intValue int32
	// strtod result
	doubleBits uint64
	doubleN    int
}

type longResult struct {
	value    int64
	n        int
	overflow bool
}

// decodeCorpusString decodes the escapes of a corpus case line (without
// the leading '>'): "\\", "\xHH" and "\R<count>:<HH>".
func decodeCorpusString(s string) (string, error) {
	var b strings.Builder
	for i := 0; i < len(s); {
		if s[i] != '\\' {
			b.WriteByte(s[i])
			i++
			continue
		}
		switch {
		case strings.HasPrefix(s[i:], `\\`):
			b.WriteByte('\\')
			i += 2
		case strings.HasPrefix(s[i:], `\x`) && i+4 <= len(s):
			v, err := strconv.ParseUint(s[i+2:i+4], 16, 8)
			if err != nil {
				return "", fmt.Errorf("bad \\x escape at %d: %w", i, err)
			}
			b.WriteByte(byte(v))
			i += 4
		case strings.HasPrefix(s[i:], `\R`):
			colon := strings.IndexByte(s[i:], ':')
			if colon < 0 || i+colon+3 > len(s) {
				return "", fmt.Errorf("bad \\R escape at %d", i)
			}
			count, err := strconv.Atoi(s[i+2 : i+colon])
			if err != nil {
				return "", fmt.Errorf("bad \\R count at %d: %w", i, err)
			}
			v, err := strconv.ParseUint(s[i+colon+1:i+colon+3], 16, 8)
			if err != nil {
				return "", fmt.Errorf("bad \\R byte at %d: %w", i, err)
			}
			b.WriteString(strings.Repeat(string([]byte{byte(v)}), count))
			i += colon + 3
		default:
			return "", fmt.Errorf("bad escape at %d", i)
		}
	}
	return b.String(), nil
}

// loadCorpus reads testdata/corpus.txt and testdata/expected.txt and
// pairs every case with its C results.
func loadCorpus(t *testing.T) []corpusCase {
	t.Helper()
	lines := readCaseLines(t, "testdata/corpus.txt")
	results := readCaseLines(t, "testdata/expected.txt")
	if len(lines) != len(results) {
		t.Fatalf("corpus has %d cases, expected.txt %d: regenerate with reference/harness/cconv/gen.sh",
			len(lines), len(results))
	}
	cases := make([]corpusCase, 0, len(lines))
	for i, line := range lines {
		echo, fields, ok := strings.Cut(results[i], "\t")
		if !ok || echo != line {
			t.Fatalf("expected.txt line for case %q does not match the corpus (got %q)", line, echo)
		}
		input, err := decodeCorpusString(line[1:])
		if err != nil {
			t.Fatalf("case %q: %v", line, err)
		}
		c := corpusCase{line: line, input: input, long: map[int]longResult{}}
		for f := range strings.FieldsSeq(fields) {
			if err := c.parseResult(f); err != nil {
				t.Fatalf("case %q: result %q: %v", line, f, err)
			}
		}
		cases = append(cases, c)
	}
	return cases
}

func (c *corpusCase) parseResult(f string) error {
	key, val, ok := strings.Cut(f, "=")
	if !ok {
		return fmt.Errorf("missing '='")
	}
	parts := strings.Split(val, ",")
	switch {
	case key == "i":
		v, err := strconv.ParseInt(val, 10, 32)
		c.intValue = int32(v)
		return err
	case key == "d" && len(parts) == 3:
		bits, err := strconv.ParseUint(parts[0], 16, 64)
		if err != nil {
			return err
		}
		n, err := strconv.Atoi(parts[1])
		c.doubleBits, c.doubleN = bits, n
		return err
	case strings.HasPrefix(key, "l") && len(parts) == 3:
		base, err := strconv.Atoi(key[1:])
		if err != nil {
			return err
		}
		v, err := strconv.ParseInt(parts[0], 10, 64)
		if err != nil {
			return err
		}
		n, err := strconv.Atoi(parts[1])
		if err != nil {
			return err
		}
		c.long[base] = longResult{value: v, n: n, overflow: parts[2] == "1"}
		return nil
	}
	return fmt.Errorf("unknown result")
}

// readCaseLines returns the lines of a corpus or expected-results file
// that start with '>'.
func readCaseLines(t *testing.T, path string) []string {
	t.Helper()
	f, err := os.Open(path)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 0, 64*1024), 1<<20)
	lines := []string{}
	for sc.Scan() {
		if strings.HasPrefix(sc.Text(), ">") {
			lines = append(lines, sc.Text())
		}
	}
	if err := sc.Err(); err != nil {
		t.Fatal(err)
	}
	return lines
}
